head.script:
// =============================================================================
/**
 * stf 업무 모듈에서 추출한 업무공통(KRX 고유) 함수.
 * 데이터셋 복사 / 콤보 데이터셋 / 그리드 헤더·패널 메시지 / 기간·일자 UI /
 * 업무번호 생성 / 공시뷰어 / 로그저장 / 연결주석 사유.
 * 함수명은 camelCase 로 표준화하고, 각 JSDoc 에 AS-IS 원본명(origin: stf.xml)을 병기한다.
 * 인쇄/리포트(report.xml, *_print.xml) 함수는 본 파일에 두지 않고 print.xml($c.print)로 분리한다.
 *
 * 단순 문자열/숫자/날짜/검증/팝업/세션 함수는 기존 $c.* 공통함수로 매핑(이관)되었으며 본 파일에 포함하지 않는다.
 * 매핑 내역은 src/as-is/stf/md/gcc_mapping_and_biz_common.md 참조.
 *
 * @author Inswave Systems
 * @class stf
 * @namespace $c.stf
 */
// =============================================================================

scwin.onpageload = function () {

};

scwin.glb = {};


// 화면처리구분코드 (Action 클래스를 거치지 않는 엑셀다운로드 등 로그 기록 시 사용)
scwin.glb.SCREN_PROCS_TP_CD_01 = "01"; // 조회
