scwin.glb.SCREN_PROCS_TP_CD_05 = "05"; // 인쇄
scwin.glb.SCREN_PROCS_TP_CD_06 = "06"; // 화면출력
scwin.glb.SCREN_PROCS_TP_CD_07 = "07"; // 엑셀저장
scwin.glb.SCREN_PROCS_TP_CD_08 = "08"; // PC저장

scwin.glb.TR_JOB_NORMAL = 1;
scwin.glb.TR_JOB_INSERT = 2;
scwin.glb.TR_JOB_UPDATE = 3;
scwin.glb.TR_JOB_DELETE = 4;

const UNDER_BAR = "_";

