	{ key: "MSG-0903", content: " ·법인 제출과 금융감독원 접수가 마감되었습니다.\n ·업무 마감을 하실 수 있습니다." },
	{ key: "MSG-0904", content: " ·법인 제출과 금융감독원 접수가 마감되었습니다.\n ·업무가 마감되었습니다." },
	{ key: "MSG-0905", content: " ·현재 모든 업무가 마감되었습니다." },
	{ key: "MSG-0906", content: " ·법인 제출이 진행중입니다." },
	{ key: "MSG-0907", content: "이미 공시처리되었습니다. 정정공시처리하시겠습니까?" },
	{ key: "MSG-0908", content: "원본 데이터를 조회할 수 없어 공시문서를 생성할 수 없습니다." },
	{ key: "MSG-0909", content: "변경사항을 저장한 후에 수행할 수 있습니다. 저장후 후 처리하세요." },
	{ key: "MSG-0910", content: "[^]의 형식이 옳바르지 않습니다." },
	{ key: "MSG-0911", content: "[^]은 5자리입니다." },
	{ key: "MSG-0912", content: " ·법인 제출이 마감되었습니다.\n ·업무가 마감되었습니다." },
	{ key: "MSG-0913", content: " ·법인 제출이 진행중입니다.\n ·업무가 마감되었습니다." }
];

/**	
 * 
 * 1. 설 명
 *    파라미터로 들어온 Key값을 이용하여 해당 Message를 출력한다.
 *
 * 2. 특이사항
 *    key와 일치하는 값이 없을 경우 해당 key값을 리턴한다.
 * 
 * <b>Parameters</b>
 *    key : 해당 메세지를 출력하기 위한 key값.
 *    targetMsg : key에 포함시킬 메세지
 * 
 * <b>return</b>
 *    content : 해당 메세지를 조합한  후 얻은 결과값.
 *
 * [[사용예]]
 *  => $c.win.alert( $c.stf.getMessageParam("MSG-0001", "개인정보수정") );
 */
/**
 * @method
 * @name getMessageParam
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.getMessageParam = function (key, targetMsg) {
	var flag = false;
	var content;
	for (i = 0; i < scwin.messageKeys.length; i++) {
		if (key == scwin.messageKeys[i].key) {
			content = scwin.messageKeys[i].content;
			flag = true;
			break;
		}
	}
	if (content == undefined) content = "MessageCode: " + key;
	if (flag == false) content = "MessageCode: " + key;

	var count = content.indexOf("^");
	if (count > -1) {
		content = content.substring(0, count) + targetMsg + content.substring(count + 1);
	}
	return content;
}

// -----------------------------------------------------------------------------
// 1. 데이터셋/그리드 보조 (origin: stf.xml)
// -----------------------------------------------------------------------------

/**
 * @method
 * @name copyDataSet
 * @description 데이터셋 오브젝트 간에 데이터를 복사한다. 복사대상 데이터셋의 기존 데이터는 모두 삭제된다.
 * features 의 copyHeader=yes 면 컬럼 헤더까지 복사한다.
 * (AS-IS: CopyDataSet, origin: stf.xml)
 * @param {Object} oOriginDataSet 원본 DataSet
 * @param {Object} oTargetDataSet 복사 대상 DataSet
 * @param {String} features 옵션 문자열 (copyHeader/resetStatus/rowFrom/rowCnt). 예: "copyHeader=yes,rowFrom=1,rowCnt=2"
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.stf.copyDataSet(oOrigin, oTarget, "copyHeader=no");
 */
scwin.copyDataSet = function (oOriginDataSet, oTargetDataSet, features) {
	var featureNames = ["copyHeader", "resetStatus", "rowFrom", "rowCnt"];
	var featureValues = [true, true, 1, oOriginDataSet.getTotalRow()];
	var featureTypes = ["boolean", "boolean", "number", "number"];
	if (features != null) {
		scwin.__cfParseFeature(features, featureNames, featureValues, featureTypes);
	}
	var copyHeader = featureValues[0];
	var resetStatus = featureValues[1];
	var rowFrom = featureValues[2];
	var rowCnt = featureValues[3];
	if (copyHeader == true) {
		scwin.copyDataSetHeader(oOriginDataSet, oTargetDataSet);
	}
	oTargetDataSet.ClearData();
	if (oOriginDataSet.getTotalRow() > 0) {
		var temp = oTargetDataSet.dataid; // ImportData 후 기존 dataid 속성이 지워지는 것을 방지.
		oTargetDataSet.ImportData(oOriginDataSet.ExportData(rowFrom, rowCnt, true));
		oTargetDataSet.dataid = temp;
		if (resetStatus == true) {
			oTargetDataSet.ResetStatus();
		}
	}
};

/**
 * @method
 * @name copyDataSetHeader
 * @description 데이터셋 오브젝트 간에 컬럼 헤더(컬럼ID/타입/사이즈/속성) 정보를 복사한다.
 * (AS-IS: CopyDataSetHeader, origin: stf.xml)
 * @param {Object} oOriginDataSet 원본 DataSet
 * @param {Object} oTargetDataSet 복사 대상 DataSet
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.stf.copyDataSetHeader(oOrigin, oTarget);
 */
scwin.copyDataSetHeader = function (oOriginDataSet, oTargetDataSet) {
	var DsHeader = "";
	var colId = "";
	var colType = "";
	var colProp = "";
	var colSize = "";
	var colDec = "";
	var colIndex = "";
	scwin.__copyDataSetHeaderDummy(oTargetDataSet);
	for (var i = 1; i <= oOriginDataSet.getTotalCol(); i++) {
		colId = oOriginDataSet.ColumnID(i);
		colIndex = oOriginDataSet.ColumnIndex(colId);
		colSize = oOriginDataSet.ColumnSize(colIndex);
		colDec = oOriginDataSet.ColumnDec(colIndex);
		switch (oOriginDataSet.ColumnType(colIndex)) {
			case 1: colType = "String"; break;
			case 2: colType = "Integer"; break;
			case 3: colType = "Decimal"; break;
			case 4: colType = "Date"; break;
			case 5: colType = "URL"; break;
			case 9: colType = "BIGINT"; break;
			default: colType = ""; break;
		}
		switch (oOriginDataSet.ColumnProp(i)) {
			case 0: colProp = "NORMAL"; break;
			case 1: colProp = "CONSTANT"; break;
			case 2: colProp = "KEYVALUE"; break;
			default: colProp = ""; break;
		}
		if (colType == "Decimal") {
			DsHeader = DsHeader + colId + ":" + colType + "(" + colSize + "." + colDec + "):" + colProp + ",";
		} else {
			DsHeader = DsHeader + colId + ":" + colType + "(" + colSize + "):" + colProp + ",";
		}
	}
	DsHeader = DsHeader.substr(0, DsHeader.length - 1);
	oTargetDataSet.SetDataHeader(DsHeader);
};

/**
 * @method
 * @name copyDataSetForTemp
 * @description 매매거래정지 임시보관함 전송 시 사용하는 데이터셋 복사. copyDataSet 과 동일하되
 * 헤더 복사를 copyDataSetHeaderForTemp(특정 컬럼 사이즈 보정)로 처리한다.
 * (AS-IS: CopyDataSetForTemp, origin: stf.xml)
 * @param {Object} oOriginDataSet 원본 DataSet
 * @param {Object} oTargetDataSet 복사 대상 DataSet
 * @param {String} features 옵션 문자열 (copyHeader/resetStatus/rowFrom/rowCnt)
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.stf.copyDataSetForTemp(oOrigin, oTarget, "copyHeader=yes");
 */
scwin.copyDataSetForTemp = function (oOriginDataSet, oTargetDataSet, features) {
	var featureNames = ["copyHeader", "resetStatus", "rowFrom", "rowCnt"];
	var featureValues = [true, true, 1, oOriginDataSet.getTotalRow()];
	var featureTypes = ["boolean", "boolean", "number", "number"];
	if (features != null) {
		scwin.__cfParseFeature(features, featureNames, featureValues, featureTypes);
	}
	var copyHeader = featureValues[0];
	var resetStatus = featureValues[1];
	var rowFrom = featureValues[2];
	var rowCnt = featureValues[3];
	if (copyHeader == true) {
		scwin.copyDataSetHeaderForTemp(oOriginDataSet, oTargetDataSet);
	}
	oTargetDataSet.ClearData();
	if (oOriginDataSet.getTotalRow() > 0) {
		var temp = oTargetDataSet.dataid;
		oTargetDataSet.ImportData(oOriginDataSet.ExportData(rowFrom, rowCnt, true));
		oTargetDataSet.dataid = temp;
		if (resetStatus == true) {
			oTargetDataSet.ResetStatus();
		}
	}
};

/**
 * @method
 * @name copyDataSetHeaderForTemp
 * @description 임시보관함용 데이터셋 헤더 복사. copyDataSetHeader 와 동일하되
 * TRD_HALT_TP_NM 컬럼 사이즈를 80 으로 보정한다.
 * (AS-IS: CopyDataSetHeaderForTemp, origin: stf.xml)
 * @param {Object} oOriginDataSet 원본 DataSet
 * @param {Object} oTargetDataSet 복사 대상 DataSet
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.stf.copyDataSetHeaderForTemp(oOrigin, oTarget);
 */
scwin.copyDataSetHeaderForTemp = function (oOriginDataSet, oTargetDataSet) {
	var DsHeader = "";
	var colId = "";
	var colType = "";
	var colProp = "";
	var colSize = "";
	var colDec = "";
	var colIndex = "";
	scwin.__copyDataSetHeaderDummy(oTargetDataSet);
	for (var i = 1; i <= oOriginDataSet.getTotalCol(); i++) {
		colId = oOriginDataSet.ColumnID(i);
		colIndex = oOriginDataSet.ColumnIndex(colId);
		colSize = oOriginDataSet.ColumnSize(colIndex);
		colDec = oOriginDataSet.ColumnDec(colIndex);
		switch (oOriginDataSet.ColumnType(colIndex)) {
			case 1: colType = "String"; break;
			case 2: colType = "Integer"; break;
			case 3: colType = "Decimal"; break;
			case 4: colType = "Date"; break;
			case 5: colType = "URL"; break;
			case 9: colType = "BIGINT"; break;
			default: colType = ""; break;
		}
		switch (oOriginDataSet.ColumnProp(i)) {
			case 0: colProp = "NORMAL"; break;
			case 1: colProp = "CONSTANT"; break;
			case 2: colProp = "KEYVALUE"; break;
			default: colProp = ""; break;
		}
		if (colType == "Decimal") {
			DsHeader = DsHeader + colId + ":" + colType + "(" + colSize + "." + colDec + "):" + colProp + ",";
		} else {
			if (colId == "TRD_HALT_TP_NM") {
				colSize = 80;
			}
			DsHeader = DsHeader + colId + ":" + colType + "(" + colSize + "):" + colProp + ",";
		}
	}
	DsHeader = DsHeader.substr(0, DsHeader.length - 1);
	oTargetDataSet.SetDataHeader(DsHeader);
};

/**
 * @method
 * @name __copyDataSetHeaderDummy
 * @description (내부) 복사 대상 데이터셋을 더미 헤더 메시지로 초기화한다. copyDataSetHeader 보조.
 * (AS-IS: CopyDataSetHeaderDummy, origin: stf.xml)
 * @param {Object} oTargetDataSet 대상 DataSet
 * @returns {void}
 * @hidden Y
 * @exception
 * @example scwin.__copyDataSetHeaderDummy(oTarget);
 */
scwin.__copyDataSetHeaderDummy = function (oTargetDataSet) {
	var oldSyscLoad = oTargetDataSet.SyncLoad;
	oTargetDataSet.SyncLoad = true;
	oTargetDataSet.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DUMMY_INOUT";
	oTargetDataSet.reset();
	oTargetDataSet.SyncLoad = oldSyscLoad;
};

/**
 * @method
 * @name __cfParseFeature
 * @description (내부) feature 문자열("name=value,...")을 파싱하여 값/타입 배열에 셋팅한다. copyDataSet 계열 보조.
 * (AS-IS: cfParseFeature, origin: stf.xml)
 * @param {String} features feature 문자열
 * @param {Array} fNameArray 추출할 feature 이름 배열
 * @param {Array} fValueArray 기본값 배열(결과가 채워짐)
 * @param {Array} fTypeArray 데이터 타입 배열(string/number/boolean)
 * @returns {void}
 * @hidden Y
 * @exception
 * @example scwin.__cfParseFeature(features, names, values, types);
 */
scwin.__cfParseFeature = function (features, fNameArray, fValueArray, fTypeArray) {
	if (features == null) {
		return;
	}
	var featureArray = features.split(",");
	var featurePair;
	for (var i = 0; i < featureArray.length; i++) {
		featurePair = $c.str.trim(featureArray[i]).split("=");
		for (var j = 0; j < fNameArray.length; j++) {
			if (featurePair[0] == fNameArray[j]) {
				switch (fTypeArray[j]) {
					case "string":
						fValueArray[j] = featurePair[1];
						break;
					case "number":
						fValueArray[j] = Number(featurePair[1]);
						break;
					case "boolean":
						if (featurePair[1].toUpperCase() == "YES" || featurePair[1].toUpperCase() == "TRUE" || featurePair[1] == "1") {
							fValueArray[j] = true;
						} else {
							fValueArray[j] = false;
						}
						break;
				}
			}
		}
	}
};

/**
 * @method
 * @name fillGridHeaderTotalCnt
 * @description 페이징 없이 전체 건수만 표시할 때 그리드 헤더 패널에 건수를 표시한다.
 * (AS-IS: FillGridHeaderTotalCnt, origin: stf.xml)
