/**
 * @method
 * @name checkDutyTimeStatus
 * @description 당번 개시/마감 등록정보를 조회하여 데이터셋에 채운다. (NOW_DUTY_YN/NOW_DUTY_STAT/PROCS_YN/TEAM_SAME_YN)
 * (AS-IS: fn_checkDutyTimeStatus, origin: stf.xml)
 * @param {String} pEmpNo 사원번호
 * @param {String} pAcptNo 접수번호
 * @param {Object} pDtsObj 결과를 받을 DataSet
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.stf.checkDutyTimeStatus(empNo, acptNo, dts_duty);
 */
scwin.checkDutyTimeStatus = function (pEmpNo, pAcptNo, pDtsObj) {
	var url = "/PersonOnDuty.do?method=checkDisclsDutyHistory";
	url += "&EmpNo=" + pEmpNo;
	url += "&AcptNo=" + pAcptNo;
	pDtsObj.DataID = encodeURI(url);
	pDtsObj.Reset();
};

/**
 * @method
 * @name openDisclViewer
 * @description 공시뷰어 화면을 연다. pScrenID 는 비공개 첨부서류 표시 여부 판단을 위해 호출 화면 아이디를 넘긴다.
 * (AS-IS: fn_OpenDisclViewer, origin: stf.xml) — AS-IS 의 2인자/3인자 중복정의를 pScrenID 선택적 인자 단일 정의로 통합.
 * @param {String} pAcptNo 접수번호
 * @param {String} pViewerStat 처리버튼 생성타입 (R 또는 P)
 * @param {String} pScrenID 호출 화면 아이디 (옵션, 비공개 첨부서류 표시용)
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.stf.openDisclViewer(acptNo, "R", scwin.SCREN_ID);
 */
scwin.openDisclViewer = async function (pAcptNo, pViewerStat, pScrenID) {
	if (pScrenID == undefined) pScrenID = "";
	// $c.frame 사용 중단 — 톱 WinOpen 대신 browserPopup, frame.FrameID 는 현재 프레임 id 로 대체
	const url = "/dsclproc/ULDSTF10001.gfm?gAcptNo=" + pAcptNo + "&gViewerStat=" + pViewerStat + "&frameID=" + $p.getFrameId() + "&gAccssAuthTpCd=01&gAskScrenID=" + pScrenID;

	const options = {
		id: "viewer" + pAcptNo,
		popupName: "공시뷰어",
		type: "browserPopup",
		width: "1000px",
		height: "800px"
	};

	$c.win.openPopup(url, options);
};

/**
 * @method
 * @name openNoDisclViewer
 * @description 미공개 공시뷰어를 연다. 당번 부서직책이 팀원이면 당번지정시간에만, 팀장이면 타팀 종목도 조회/처리 가능하도록
 * 당번 상태(checkDutyTimeStatus)를 점검한 뒤 권한이 있으면 openDisclViewer 를 호출한다.
 * (AS-IS: fn_OpenNoDisclViewer, origin: stf.xml) — AS-IS 의 9인자/10인자 중복정의를 pScrenID 선택적 인자 단일 정의로 통합.
 * @param {String} pAcptNo 접수번호
 * @param {String} pViewerStat 처리버튼 생성타입 (R 또는 P)
 * @param {String} pEmpNo 사원번호
 * @param {String} pDepCd 부서코드
 * @param {String} pJobtitl 부서직책
 * @param {String} pDuty 당번여부
 * @param {String} pDutyChrg 당번책임여부
 * @param {String} pScrnTpCd 화면구분코드 (P:담당자검토, M:책임자승인, S:공시처리현황)
 * @param {Object} pDtsObj 당번상태 조회 DataSet
 * @param {String} pScrenID 호출 화면 아이디 (옵션)
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.stf.openNoDisclViewer(acptNo, "R", empNo, depCd, jobtitl, duty, dutyChrg, "P", dts_duty, scwin.SCREN_ID);
 */
scwin.openNoDisclViewer = function (pAcptNo, pViewerStat, pEmpNo, pDepCd, pJobtitl, pDuty, pDutyChrg, pScrnTpCd, pDtsObj, pScrenID) {
	if (pScrenID == undefined) pScrenID = "";
	var gDutyTimeYn = "Y";
	var gNowDutyYn = "";    // 현재시점 당번여부
	var gNowDutyStat = "";  // 현재시점 당번상태 S:개시, E:마감, N:미등록
	var gProcsYn = "";
	var gTeamSameYn = "";

	// 공시 관련 부서코드만 당번시간 체크 대상
	var dutyDeptArr = ["2600", "2611", "2620", "2630", "2640", "2650", "2660",
		"3400", "3420", "3430", "3440", "3460", "3490", "3495", "3470", "3480"];

	if (scwin.__isInArr(pDepCd, dutyDeptArr)) {
		if (pJobtitl == "09" || pJobtitl == "40") {
			// 직책 09/40 은 당번시간 제한 없음
		} else {
			scwin.checkDutyTimeStatus(pEmpNo, pAcptNo, pDtsObj);
			gNowDutyYn = pDtsObj.getCellData(1, "NOW_DUTY_YN");
			gNowDutyStat = pDtsObj.getCellData(1, "NOW_DUTY_STAT");
			gProcsYn = pDtsObj.getCellData(1, "PROCS_YN");
			gTeamSameYn = pDtsObj.getCellData(1, "TEAM_SAME_YN");
			if (gProcsYn == "N") {
				if (gNowDutyYn == "Y" || pDuty == "Y" || pDutyChrg == "Y") {
					if (gNowDutyYn == "Y") {
						if (gNowDutyStat == "S") {
							// 개시상태 - 조회/처리 가능
						} else {
							if (pScrnTpCd == "M" || gTeamSameYn != "Y") {
								// 책임자승인에서는 개시상태가 아니면 담당종목도 조회불가
								gDutyTimeYn = "N";
								alert("[당번업무 시작 권한 부여] 후에 공시조회/처리를 하실 수 있습니다.");
							}
						}
					} else {
						if (gTeamSameYn != "Y") {
							gDutyTimeYn = "N";
							alert("[당번업무]가 종료되었습니다.");
						}
					}
				}
			}
		}
	}
	if (gDutyTimeYn == "Y") {
		scwin.openDisclViewer(pAcptNo, pViewerStat, pScrenID);
	}
};

/**
 * @method
 * @name __isInArr
 * @description (내부) 값이 배열에 포함되는지 여부를 반환한다. openNoDisclViewer 의 부서코드 매칭 보조.
 * @param {String} val 찾을 값
 * @param {Array} arr 대상 배열
 * @returns {Boolean} 포함 여부
 * @hidden Y
 * @exception
 * @example scwin.__isInArr("2600", arr);
 */
scwin.__isInArr = function (val, arr) {
	for (var i = 0; i < arr.length; i++) {
		if (arr[i] == val) return true;
	}
	return false;
};

/**
