// -----------------------------------------------------------------------------
// 7. 로그 저장 (Action 클래스를 거치지 않는 처리의 활동 로그) (origin: stf.xml)
// -----------------------------------------------------------------------------

scwin.xmlHttp4LogSave = null;   // XMLHttpRequest 객체
scwin.alert4LogSave = false;    // 로그 결과 alert 여부

/**
 * @method
 * @name doLogSave
 * @description 활동 로그 저장을 실행한다. (XMLHttpRequest 객체 생성 → 로그 저장 URL 호출)
 * (AS-IS: doLogSave, origin: stf.xml)
 * @param {String} ver1 화면 ID (SCREN_ID)
 * @param {String} ver2 화면처리구분코드 (SCREN_PROCS_TP_CD_*)
 * @param {Boolean} ver3 결과 alert 여부 (옵션)
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.stf.doLogSave(scwin.SCREN_ID, scwin.SCREN_PROCS_TP_CD_07);
 */
scwin.doLogSave = function (ver1, ver2, ver3) {
	scwin.createXmlObj4LogSave();
	if (ver3) scwin.alert4LogSave = true;
	scwin.startLogSave(ver1, ver2);
};

/**
 * @method
 * @name createXmlObj4LogSave
 * @description 로그 저장용 XMLHttpRequest 객체를 생성한다.
 * (AS-IS: createXMLObj4LogSave, origin: stf.xml)
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.stf.createXmlObj4LogSave();
 */
scwin.createXmlObj4LogSave = function () {
	if (window.ActiveXObject) {
		scwin.xmlHttp4LogSave = new ActiveXObject("Microsoft.XMLHTTP");
	} else if (window.XMLHttpRequest) {
		scwin.xmlHttp4LogSave = new XMLHttpRequest();
	}
};

/**
 * @method
 * @name startLogSave
 * @description 로그 저장 URL(logSaveAct.jsp)을 비동기 호출한다.
 * (AS-IS: startLogSave, origin: stf.xml)
 * @param {String} ver1 화면 ID (SCREN_ID)
 * @param {String} ver2 화면처리구분코드 (SCREN_PROCES_TP_CD)
 * @returns {void}
 * @hidden N
 * @exception
 * @example $c.stf.startLogSave(scwin.SCREN_ID, scwin.SCREN_PROCS_TP_CD_07);
 */
scwin.startLogSave = function (ver1, ver2) {
	var url = "/common/logSaveAct.jsp?SCREN_ID=" + ver1 + "&SCREN_PROCES_TP_CD=" + ver2;
	scwin.xmlHttp4LogSave.onreadystatechange = scwin.__chkStats4LogSave;
	scwin.xmlHttp4LogSave.open("GET", url, true);
	scwin.xmlHttp4LogSave.send(null);
};

/**
 * @method
 * @name __chkStats4LogSave
 * @description (내부) 로그 저장 요청의 readyState/status 를 점검하고 완료 시 결과를 확인한다.
 * (AS-IS: chkStats4LogSave, origin: stf.xml)
 * @returns {void}
 * @hidden Y
 * @exception
 * @example onreadystatechange 콜백
 */
scwin.__chkStats4LogSave = function () {
	if (scwin.xmlHttp4LogSave.readyState == 4) {
		if (scwin.xmlHttp4LogSave.status == 200) {
			scwin.__viewParameter4LogSave();
		}
	}
};

/**
 * @method
 * @name __viewParameter4LogSave
 * @description (내부) 로그 저장 응답(result)을 파싱하여 alert4LogSave 가 true 면 결과를 표시한다.
 * (AS-IS: viewParameter4logSave, origin: stf.xml)
 * @returns {void}
 * @hidden Y
 * @exception
 * @example 내부 콜백
 */
scwin.__viewParameter4LogSave = function () {
	var xmlDoc = scwin.xmlHttp4LogSave.responseXML;
	var node = xmlDoc.getElementsByTagName("result");
	if (scwin.alert4LogSave) alert(node[0].childNodes[0].nodeValue);
};

