 */
scwin.getConnRsnCdNm1 = function (pCode) {
	var str = "";
	if (pCode == "01") {
		str += "주식회사가 다른 회사의 의결권있는 주식 또는 출자지분의 100분의 50을 초과하여 소유하는 경우 \n";
		str += "(외감법시행령 제1조의3 1항1호)";
	} else if (pCode == "02") {
		str += "주식회사가 다른 회사의 의결권있는 주식등의 100분의 30을 초과하여 소유하면서 당해 다른 회사의 최다출자자인 경우 \n";
		str += "(외감법시행령 제1조의3 1항2호)";
	} else if (pCode == "03") {
		str += "지배회사와 종속회사가 합하거나, 종속회사와 종속회사가 합하여 다른 회사의 의결권 있는 주식등의 100분의 30을 초과하여 소유하면서 당해 다른 회사의 최다출자자인 경우 \n";
		str += "(외감법시행령 제1조의3 1항3호)";
	} else if (pCode == "04") {
		str += "주식회사가 계약 또는 전환사채ㆍ신주인수권부사채 등의 권리행사에 의하여 의결권있는 주식등의 100분의 50을 초과하여 그 의결권을 행사할 수 있는 권한이 있는 경우 \n";
		str += "(외감법시행령 제1조의3 1항4호)";
	} else if (pCode == "05") {
		str += "주식회사가 계약 등에 의하여 다른 회사의 이사회 또는 이에 준하는 의사결정기구의 구성원의 과반수 이상을 임면할 수 있는 권한이 있는 경우 \n";
		str += "(외감법시행령 제1조의3 1항5호)";
	} else if (pCode == "06") {
		str += "주식회사가 계약 등에 의하여 다른회사의 주주총회 또는 이에 준하는 의사결정기구의 의사결정에 있어서 과반수 이상의 의결권을 행사할 수 있는 권한이 있는 경우 \n";
		str += "(외감법시행령 제1조의3 1항6호)";
	} else if (pCode == "07") {
		str += "기타 주식회사가 다른 회사의 재무 또는 영업에 관한 중요한 사항을 결정할 수 있는 권한이 있는 경우로서 금융감독위원회가 정하는 경우 \n";
		str += "(외감법시행령 제1조3 1항7호)";
	} else if (pCode == "08") {
		str += "사유의 구별을 할 수 없는 경우";
	} else if (pCode == "21") {
		str += "지배기업이 직접으로 또는 종속기업을 통하여 간접으로 기업 의결권의 과반수를 소유하는 경우 \n";
		str += "(한국채택국제회계기준서 제1027호 연결재무제표와 별도재무제표 문단10)";
	} else if (pCode == "22") {
		str += "다른 투자자와의 약정으로 과반수의 의결권을 행사할 수 있는 능력이 있는 경우 \n";
		str += "(한국채택국제회계기준서 제1027호 연결재무제표와 별도재무제표 문단10 (1))";
	} else if (pCode == "23") {
		str += "법규나 약정에 따라 기업의 재무정책과 영업정책을 결정할 수 있는 능력이 있는 경우 \n";
		str += "(한국채택국제회계기준서 제1027호 연결재무제표와 별도재무제표 문단10 (2))";
	} else if (pCode == "24") {
