/**
 * @method
 * @name getObjectValue
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.getObjectValue = function (obj) {
	if (typeof obj != "object") {
		return;
	}

	if (typeof obj.getValue != "undefined" && typeof obj.getValue == "function") {
		return $c.str.trim(obj.getValue());
	}
	return;
}

/**
 * @method
 * @name setObjectValue
 * @description
 * @param
 * @hidden N
 * @exception
 * @example
 */
scwin.setObjectValue = function (obj, value) {
	if (typeof obj != "object") {
		return;
	}

	if (typeof obj.setValue != "undefined" && typeof obj.setValue == "function") {
		obj.setValue(value);
	}
	return;
}

/**
 * @method
 * @name checkMaxLength
 * @description max length 체크하기 위한 함수.
 * @param {Object} obj  : 체크하고자하는 object
 * @param {String} size : max length
 * @param {String} lbl  : 체크하고자 하는 항목의 label
 * @hidden N
 * @exception
 * @example
 */
scwin.checkMaxLength = function (obj, size, lbl) {
	var overLen = eval(scwin.getStringSize(scwin.getObjectValue(obj)) - size);

	if (overLen > 0) {
		$c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ "
			+ overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
		obj.focus();
		return false;
	}

	return true;
}


/**
 * @method
 * @name getStringSize
 * @description 한글을 포함한 글자의 사이즈를 구하기 위한 함수.
 * @param {String} message
 * @hidden N
 * @exception
 * @example
 */
scwin.getStringSize = function (message) {
	var i, len = 0;

	for (i = 0; i < message.length; i++) {
		(message.charCodeAt(i) > 255) ? len += 2 : len++;
	}

	return len;
}

