/**
 * @method
 * @name downloadExcel
 * @description 엑셀 다운로드
 * @param {Object} grdObj. 그리드 ID
 * @param {Object} option. excel option
 * @returns 
 * @hidden N
 * @exception
 * @example 
	const bzTitleNm = ""; // 업무기능명. 팝업화면인경우 [팝업명_업무기능명] 형태
	const optionObj = {type: "1", useStyle : "true", useClass : "true"};    // 엑셀 옵션
	$c.stf.downloadExcel(bzTitleNm, grd_list, optionObj); 
	$c.stf.downloadExcel(bzTitleNm, grd_list);
 */
scwin.downloadExcel = function (bzTitleNm, grdObj, optionObj) {
	let menuInfo = $c.data.getParameter("menuInfo");

	if (menuInfo) {
		let menuSrc = menuInfo?.src ?? "";           // 업무화면 경로. ex) "/ui/dis/dsclmgt/ULDSTF30200.xml"
		let menuNm = menuInfo?.menuNm ?? ""; // 업무화면명. ex) 조회공시 관리
		let bzTitleStr = (bzTitleNm ? bzTitleNm + " " : "") + "목록";
		let tdayTm = $c.date.getServerDateTime("yyyyMMddHHmmss");   // 현재시간. ex) 20260101093010

		let menuId = "";     // 업무화면 ID

		if (menuSrc && (menuSrc.lastIndexOf("/") > -1 && menuSrc.lastIndexOf(".xml") > -1)) {
			menuId = menuSrc.substring(menuSrc.lastIndexOf("/") + 1, menuSrc.lastIndexOf(".xml"));
		}

		/** 
		 * 파일명 형식
		 * 화면ID_업무화면명_업무기능명_yyyyMMddHHmmss.xlsx 
			ex) ULDSTF30200_조회공시 관리_목록_20260101123333.xml
		*/
		let fileNm = [menuId, menuNm, bzTitleStr, tdayTm].filter(Boolean).join(UNDER_BAR) + ".xlsx";

		// 엑셀 기본 옵션. type: "1", useStyle : "true", useClass : "true" 지정
		const defaultOption = { type: "1", useStyle: "true", useClass: "true" };

		// defaultOption + optionObj
		const options = Object.assign(defaultOption, optionObj ?? {}, { fileName: fileNm });

		$c.data.downloadGridViewExcel(grdObj, options, []);

	}

}

/**
 * yyyy년 mm월 dd일 변환
 */
/**
 * @method
 * @name formatDateEx3
 * @description desc
 * @param {string} str desc
 * @hidden N
 * @exception 
 * @example ${example}
 */
scwin.formatDateEx3 = function (str) {
	if (str == "") return "";

	var yyyy = str.substring(0, 4);
	var mm = str.substring(4, 6);
	var dd = str.substring(6, 8);
	return yyyy + "년 " + mm + "월 " + dd + "일";
}

/**
 * yyyy. mm. dd 변환
 */
/**
 * @method
 * @name formatDateEngEx1
 * @description desc
 * @param {string} str desc
 * @hidden N
 * @exception 
 * @example ${example}
 */
scwin.formatDateEngEx1 = function (str) {
	if (str == "") return "";

	var yyyy = str.substring(0, 4);
	var mm = str.substring(4, 6);
	var dd = str.substring(6, 8);
	return yyyy + ". " + mm + ". " + dd;
}

/**
 * mm. dd. yyyy 변환
 */
/**
 * @method
 * @name formatDateEngEx3
 * @description desc
 * @param {string} str desc
 * @hidden N
 * @exception 
 * @example ${example}
 */
scwin.formatDateEngEx3 = function (str) {
	if (str == "") return "";

	var mm = str.substring(0, 2);
	var dd = str.substring(2, 4);
	var yyyy = str.substring(4, 8);
	return mm + ". " + dd + ". " + yyyy;
}


