    let height = 81;
    if (param.dataList && param.dataList.length > 1) {
        for (let i = 1; i < param.dataList.length; i++) {
            height += 38;
        }
    }

    const options = {
        id: "FormInfoLayer",
        type: "pageFramePopup",
        popupName: "아래중 작성하실 보고서를 선택하세요",
        width: "500",
        height: height,
        resizable: false
    };
    $c.win.openPopup("/ui/dis/common/formInfo_layer.xml", options, param);
};

