/**
 * @method
 * @name callEditor
 * @description 편집기 호출(모달) 
 * @version 2026-08-20 버전 적용
 * @param {string} param 
 * [Query Parameter]
    - formCd (필수)
        값   : 서식코드 (예: 91370)
        설명 : 진입할 서식(본문서식) 코드. entryTpCd=AS/CR일 때는 원문서의 본문서식 코드(disclsMaindocFormCd)
    - entryTpCd (필수)
        값   : NK | NE | CR | AS
        설명 : NK = 새문서 작성(국문) / NE = 새문서 작성(영문) / CR = 정정문서 작성 / AS = 첨부문서 추가
    - lang (필수)
        값   : 0 | 1
        설명 : 언어구분코드 (0: 국문, 1: 영문)
    - formVer (entryTpCd=CR/AS이면 필수, 그 외는 선택)
        값   : 서식버전
        설명 : 특정 버전의 서식을 띄워야 할 때 사용. 미지정 시 최신 버전으로 조회. entryTpCd=AS/CR일 때는 원문서(formCd)의 버전
    - applNo (선택)
        값   : 신청번호
        설명 : 임시저장된 문서를 불러와야 할 때 사용(임시보관함 재개). 지정하면 해당 신청번호의 저장 데이터를 불러와 화면에 세팅.
               미지정 시 신규 작성으로 시작합니다.

* [Query Parameter - entryTpCd=AS 전용]
    - acptNo (필수 - 신규 진입 시)
        값   : 원문서(공시완료건) 접수번호
        설명 : 어느 완료 공시 건에 첨부서식을 추가하는지 식별하는 키. acptNo 값 기준으로 목차를 구성합니다.
    - asTargetFormCd (필수, 신규 진입 시) ★★★★★ 추가됨
        값   : 작성할 첨부서식(subdoc) formCd
        설명 : 진입 직후 자동으로 이 서식으로 이동함
    - targetFormCd (임시보관함 첨부문서 선택 시 필수) ★★★★★ 추가됨
        값   : 작성할 첨부서식(subdoc) formCd
    - addOrgnDisclsAcptNo (필수, 신규 진입 시)
        값   : 추가원공시접수번호
        설명 : AS-IS 기준 modOrgnDisclsAcptNo(정정원공시접수번호) 값을 그대로 사용
    - inqOrgnDisclsAcptNo (필수, 신규 진입 시)
        값   : 조회원공시접수번호
        설명 : acptNo와 다르면 저장 시 disclsModAddTpCd가 'A'(추가공시) 대신 'Q'(조회공시의 정정)로 처리됨
    - engOrgnDisclsAcptNo (선택, 신규 진입 시)
        값   : 영문원공시접수번호

* [Query Parameter - entryTpCd=CR 전용]
아래 4개(engOrgnDisclsAcptNo, modAddSeq 제외)는 applNo 없이 처음 진입하는 경우(아직 저장한 적 없는 신규 작성)에만 필요합니다. 빠지면 "잘못된 진입 정보입니다" 에러로 처리됩니다.

    - acptNo (필수, 신규 진입 시)
        값   : 정정 대상 원문서(공시완료건) 접수번호
        설명 : 어느 완료 공시 건을 정정하는지 식별하는 키.
                acptNo 값 기준으로 원공시접수번호를 조회하고, 원공시접수번호를 기준으로 서식코드별 최신 제출건으로 목차를 구성합니다.

    - crTargetFormCdList (필수, 신규 진입 시)
        값   : 정정할 서식코드 목록 (콤마로 구분, 예: 91370,99999)
        설명 : 정정 대상으로 미리 선택한 서식(본문/첨부, 1개 이상).
                목록에 formCd(본문서식코드)가 포함되지 않으면 첨부정정(U)으로 처리되어 진입 직후 목록의 첫 서식으로 자동 이동하며 본문 클릭이 차단됩니다.
    - modOrgnDisclsAcptNo (필수, 신규 진입 시)
        값   : 정정원공시접수번호
    - inqOrgnDisclsAcptNo (필수, 신규 진입 시)
        값   : 조회원공시접수번호
    - engOrgnDisclsAcptNo (선택, 신규 진입 시)
        값   : 영문원공시접수번호
    - modAddSeq (선택, 신규 진입 시)
        값   : 정정추가일련번호        

  ---------------------------------------------------------------------------------------------------
  # 2026-08-21
  targetFormCd(선택) 파라미터 추가. applNo(임시보관함 재개) 진입 시 진입 직후 화면에 가장 먼저 열어야 할 서식(본문 또는 첨부)을 지정할 수 있습니다.
  미지정 시 기존과 동일하게 동작합니다(첫 번째 서식으로 이동, 본문 클릭이 차단되는 경우엔 첫 번째 첨부로 대체).
  ---------------------------------------------------------------------------------------------------
 * @hidden N
 * @exception 
 * @example

    [예시]
    entryTpCd별로 "신규 진입"과 "임시보관함 진입" 두 형태를 보여줍니다.
    formVer는 NK/NE만 선택 파라미터이고(생략 시 최신 버전으로 조회) CR/AS는 필수이며, 아래 예시에는 전부 포함해서 보여줍니다.

    # NK - 새문서 작성(국문), 신규 진입 (빈 문서로 시작)
    /#/entry?formCd=91370&formVer=5.07&entryTpCd=NK&lang=0

    # NK - 새문서 작성(국문), 임시보관함 진입
    /#/entry?formCd=91370&formVer=5.07&entryTpCd=NK&lang=0&applNo=20260805001309

    # NE - 새문서 작성(영문), 신규 진입 (빈 문서로 시작)
    /#/entry?formCd=91370&formVer=5.07&entryTpCd=NE&lang=1

    # NE - 새문서 작성(영문), 임시보관함 진입
    /#/entry?formCd=91370&formVer=5.07&entryTpCd=NE&lang=1&applNo=20260805001309

    # CR - 정정문서 작성, 신규 진입 (formVer/acptNo/crTargetFormCdList 등 원공시 연결 정보 필수 - 위 [Query Parameter - entryTpCd=CR 전용] 참고)
    /#/entry?formCd=91370&formVer=5.07&entryTpCd=CR&lang=0
    &acptNo=20260812001209&crTargetFormCdList=91370
    &modOrgnDisclsAcptNo=20260806001331&inqOrgnDisclsAcptNo=20260806001331

    # CR - 정정문서 작성, 임시보관함 진입 (formVer/applNo만 필요, acptNo 등 원공시 연결 정보는 불필요)
    /#/entry?formCd=91370&formVer=5.07&entryTpCd=CR&lang=0&applNo=20260806001331

    # AS - 첨부문서 추가, 신규 진입 (formVer/acptNo/asTargetFormCd 등 원공시 연결 정보 필수 - 위 [Query Parameter - entryTpCd=AS 전용] 참고)
    /#/entry?formCd=91370&formVer=5.07&entryTpCd=AS&lang=0
    &acptNo=20260812001209&addOrgnDisclsAcptNo=20260629000405
    &inqOrgnDisclsAcptNo=20260629000405&asTargetFormCd=99999

    # AS - 첨부문서 추가, 임시보관함 진입 (formVer/applNo만 필요, acptNo 등 원공시 연결 정보는 불필요, targetFormCd로 진입 직후 열릴 첨부서식 지정)
    /#/entry?formCd=91370&formVer=5.07&entryTpCd=AS&lang=0&applNo=20260806001335
    /#/entry?formCd=91370&formVer=5.07&entryTpCd=AS&lang=0&applNo=20260806001335&targetFormCd=99999

    const param = {
        "formCd": formCd,
        "entryTpCd": entryTpCd,
        "lang": lang,
        "formVer": formVer,
        "applNo": applNo,
        "acptNo": acptNo,
        "addOrgnDisclsAcptNo": addOrgnDisclsAcptNo,
        "inqOrgnDisclsAcptNo": inqOrgnDisclsAcptNo,
        "attachFormCd": attachFormCd,
        "engOrgnDisclsAcptNo": engOrgnDisclsAcptNo
    };
    $c.dis.callEditor(param);
 * 
 */
scwin.callEditor = async function (param) {
    console.log("req", param);

    if (!param || !param.entryTpCd) {
        $c.win.alert("문서불러오기에 실패하였습니다. 잠시후 다시 해주시기 바랍니다.");
        return;
    }

    console.log("hostname", location.hostname);
    let url = "https://n-dev-editor-int.krx.co.kr/#/entry?" // "https://n-dev-editor.krx.co.kr/#/entry?"; //외부망
    // if (location.hostname === "localhost" || location.hostname === "n-idev-filing.krx.co.kr") {
    //     url = "https://n-idev-editor.krx.co.kr/#/entry?"; //내부망에서 DMZ 개발계 접속
    // }
    console.log("domain", url);

    //기본 필수값 체크
    if (param.formCd && param.entryTpCd && param.lang) {
        url += "formCd=" + param.formCd;
        url += "&entryTpCd=" + param.entryTpCd;
        url += "&lang=" + param.lang;
    } else {
        $c.win.alert("문서불러오기에 실패하였습니다. 잠시후 다시 해주시기 바랍니다.");
        return;
    }

    if (param.formVer) { url += "&formVer=" + param.formVer; }
    if (param.applNo) { url += "&applNo=" + param.applNo; }
    if (param.acptNo) { url += "&acptNo=" + param.acptNo; }
    if (param.asTargetFormCd) { url += "&asTargetFormCd=" + param.asTargetFormCd; }
    if (param.addOrgnDisclsAcptNo) { url += "&addOrgnDisclsAcptNo=" + param.addOrgnDisclsAcptNo; }
    if (param.inqOrgnDisclsAcptNo) { url += "&inqOrgnDisclsAcptNo=" + param.inqOrgnDisclsAcptNo; }
    if (param.engOrgnDisclsAcptNo) { url += "&engOrgnDisclsAcptNo=" + param.engOrgnDisclsAcptNo; }
    if (param.crTargetFormCdList) { url += "&crTargetFormCdList=" + param.crTargetFormCdList; }
    if (param.modOrgnDisclsAcptNo) { url += "&modOrgnDisclsAcptNo=" + param.modOrgnDisclsAcptNo; }
    if (param.modAddSeq) { url += "&modAddSeq=" + param.modAddSeq; }
    if (param.targetFormCd) { url += "&targetFormCd=" + param.targetFormCd; }

    if (param.tgtIsurCd) { url += "&tgtIsurCd=" + param.tgtIsurCd; }
    if (param.tgtFssUnqNo) { url += "&tgtFssUnqNo=" + param.tgtFssUnqNo; }
    if (param.tgtIsuSrtCd) { url += "&tgtIsuSrtCd=" + param.tgtIsuSrtCd; }

    console.log("최종 요청 url", url);

    const moveUrl = "/ui/dis/common/disclosure_editor_page.xml";
    const data = {
        url : url
    };

    let bSize = scwin.__getModalSize(95 ,95);
    const options = {
        id: "DisclsEditor",
        type: "pageFramePopup",        
        popupName: "문서작성",
        width: bSize.width,
        height: bSize.height,
        resizable: false
    };
    $c.win.openPopup(moveUrl, options, data);

};

/**
 * @method
 * @name __getModalSize
 * @description 사용자 브라우저의 너비, 높이 계산
 * @param {int} widthPercent 너비 비율
 * @param {int} heightPercent 높이 비율
 * @hidden N
 * @exception 
 * @example scwin.__getModalSize(95 ,95);
 */ 
scwin.__getModalSize = function (widthPercent, heightPercent) {
    return {
        width: Math.floor(window.innerWidth * (widthPercent / 100)),
        height: Math.floor(window.innerHeight * (heightPercent / 100))
    }
};

/**
 * @method
 * @name initGridSettings
 * @description 공시제출 그리드뷰 사용시 공통적으로 적용되는 설정값 세팅. 
 *              존재하는 컴포넌트만 표준 적용 됨.
 *              적용하고싶지 않은 공통은 컴포넌트를 id를 매핑하지 않으면 자동생략 됨.
 * @hidden N
 * @exception 
 * @example $c.dis.initGridSettings();
 * 
 * [필요 컴포넌트] - 없는 경우 자동생략
 *  __initPageSize : sel_size
 *  __initDateValidation : ipt_startDate, ipt_endDate
 *  __initEnterSearch : grp_search, (fn)scwin.btn_search_onclick
 */
scwin.initGridSettings = function () {
    const page = $p;
    const modules = [
        "__initPageSize",
        "__initDateValidation",
        "__initEnterSearch"
    ];

    const fnSearch = $c.util.getFunction("scwin.btn_search_onclick");

    modules.forEach(function (fnName) {
        try {
            scwin[fnName](page, fnSearch);
        } catch (e) {
            console.error(fnName, e);
        }
    });
};
/**
 * @method
 * @name __initPageSize
 * @description 페이지 사이즈 selectbox생성
 * @param {string} page 화면 컴포넌트
 * @hidden N
 * @exception 
 * @example ${example}
 */
scwin.__initPageSize = function (page) {
    const sel_size = page.getComponentById("sel_size");
    if (!sel_size) {
        return;
    }
    $c.data.comboCbDataSetDynamic(sel_size, [15, 30, 50, 100], 0);
};

/**
 * @method
 * @name __initDateValidation
 * @description 기간 유효성 검증
 * @param {string} page 화면 컴포넌트
 * @hidden N
 * @exception 
 * @example ${example}
 */
scwin.__initDateValidation = function (page) {
    const ipt_startDate = page.getComponentById("ipt_startDate");
    const ipt_endDate = page.getComponentById("ipt_endDate");
    if (!ipt_startDate || !ipt_endDate) {
        return;
    }
    $c.date.compareFromToDate(ipt_startDate, ipt_endDate, ["시작일", "종료일"], "yyyyMMdd");
};

/**
 * @method
 * @name __initEnterSearch
 * @description 엔터키 조회
 * @param {string} page 화면 컴포넌트
 * @param {function} fnSearch 조회함수
 * @hidden N
 * @exception 
 * @example ${example}
 */
scwin.__initEnterSearch = function (page, fnSearch) {
    const grp_search = page.getComponentById("grp_search");
    if (!grp_search || typeof fnSearch != "function") {
        return;
    }
    $c.win.setEnterKeyEvent(grp_search, fnSearch);
};

